CREATE TABLE ai_workflow_artifact_edges (`edge_id` String, `org_id` UUID, `run_id` String, `artifact_type` LowCardinality(String), `artifact_id` String, `provider` LowCardinality(String), `repo_id` Nullable(UUID), `confidence` Float32, `source` LowCardinality(String), `evidence` String, `observed_at` DateTime64(3, 'UTC'), `computed_at` DateTime64(3, 'UTC') DEFAULT now64()) ENGINE = ReplacingMergeTree(computed_at) PARTITION BY toYYYYMM(observed_at) ORDER BY (org_id, run_id, artifact_type, artifact_id, source) SETTINGS index_granularity = 8192

CREATE TABLE ai_workflow_runs (`run_id` String, `org_id` UUID, `provider` LowCardinality(String), `run_kind` LowCardinality(String), `status` Nullable(String), `tool` Nullable(String), `model` Nullable(String), `actor` Nullable(String), `repo_id` Nullable(UUID), `prompts_redacted` Bool, `prompt_hash` Nullable(String), `prompt_length` Nullable(UInt32), `started_at` Nullable(DateTime64(3, 'UTC')), `completed_at` Nullable(DateTime64(3, 'UTC')), `observed_at` DateTime64(3, 'UTC'), `metadata` String, `computed_at` DateTime64(3, 'UTC') DEFAULT now64()) ENGINE = ReplacingMergeTree(computed_at) PARTITION BY toYYYYMM(observed_at) ORDER BY (org_id, provider, run_id) SETTINGS index_granularity = 8192

CREATE TABLE git_commit_stats (`repo_id` UUID, `commit_hash` String, `file_path` String, `additions` Int32, `deletions` Int32, `old_file_mode` String, `new_file_mode` String, `last_synced` DateTime64(3, 'UTC'), `org_id` String DEFAULT 'default') ENGINE = ReplacingMergeTree(last_synced) ORDER BY (org_id, repo_id, commit_hash, file_path) SETTINGS index_granularity = 8192

CREATE TABLE git_commits (`repo_id` UUID, `hash` String, `message` Nullable(String), `author_name` Nullable(String), `author_email` Nullable(String), `author_when` DateTime64(3, 'UTC'), `committer_name` Nullable(String), `committer_email` Nullable(String), `committer_when` DateTime64(3, 'UTC'), `parents` UInt32, `last_synced` DateTime64(3, 'UTC'), `org_id` String DEFAULT 'default', `source_id` Nullable(UUID) DEFAULT NULL) ENGINE = ReplacingMergeTree(last_synced) ORDER BY (org_id, repo_id, hash) SETTINGS index_granularity = 8192

CREATE TABLE work_graph_edges (`edge_id` String COMMENT 'Deterministic hash of (source_type, source_id, edge_type, target_type, target_id)', `source_type` String COMMENT 'Type of source node: issue|pr|commit|file', `source_id` String COMMENT 'Source identifier: work_item_id, repo#pr, repo@sha, repo:path', `target_type` String COMMENT 'Type of target node: issue|pr|commit|file', `target_id` String COMMENT 'Target identifier', `edge_type` String COMMENT 'Relationship type: references|implements|contains|touches|blocks|relates|duplicates|etc', `repo_id` Nullable(UUID) COMMENT 'Repository UUID if applicable', `provider` Nullable(String) COMMENT 'Provider: jira|github|gitlab', `provenance` String COMMENT 'How edge was discovered: native|explicit_text|heuristic', `confidence` Float32 COMMENT 'Confidence score 0.0-1.0', `evidence` String COMMENT 'Short token or rule ID explaining discovery', `discovered_at` DateTime64(3, 'UTC') COMMENT 'When edge was first discovered', `last_synced` DateTime64(3, 'UTC') COMMENT 'Last sync timestamp for ReplacingMergeTree', `event_ts` DateTime64(3, 'UTC') DEFAULT now(), `day` Date DEFAULT toDate(event_ts), `org_id` String DEFAULT 'default', `is_deleted` UInt8 DEFAULT 0) ENGINE = ReplacingMergeTree(last_synced) ORDER BY (org_id, source_type, source_id, edge_type, target_type, target_id) SETTINGS index_granularity = 8192 COMMENT 'Generic work graph edge store with provenance tracking'

CREATE TABLE work_graph_pr_review_outcome_edges (`edge_id` String, `org_id` UUID, `pr_id` String, `review_outcome_id` String, `outcome` Nullable(String), `provider` LowCardinality(String), `repo_id` Nullable(UUID), `confidence` Float32, `source` LowCardinality(String), `evidence` String, `observed_at` DateTime64(3, 'UTC'), `computed_at` DateTime64(3, 'UTC') DEFAULT now64()) ENGINE = ReplacingMergeTree(computed_at) PARTITION BY toYYYYMM(observed_at) ORDER BY (org_id, pr_id, review_outcome_id, source) SETTINGS index_granularity = 8192
